/// Native replay implementations for device bindings.
#[inline]
fn destack_device_bluetooth_adapter_list_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeSlice<BluetoothAdapterDescriptor>,
) -> RuntimeResult<()> {
    binding.trace().run_binding_without_context(
        DEVICE_BLUETOOTH_ADAPTER_LIST,
        binding.replay_payload_for(DEVICE_BLUETOOTH_ADAPTER_LIST)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_device_bluetooth_adapter_list(binding, out)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_device_bluetooth_adapter_list(binding, out)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: NativeSlice<BluetoothAdapterDescriptor> = unsafe { out.read() };
                let result_recorded_slice = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_slice.len());
                for result_recorded_item in result_recorded_slice.iter().cloned() {
                    let result_recorded_item_recorded_id =
                        unsafe { result_recorded_item.id.as_str()? }.to_string();
                    let result_recorded_item_recorded_name =
                        unsafe { result_recorded_item.name.as_str()? }.to_string();
                    let result_recorded_item_recorded_powered = result_recorded_item.powered;
                    let result_recorded_item_recorded_discovering =
                        if let Some(value) = result_recorded_item.discovering {
                            let result_recorded_item_recorded_discovering_inner = value;
                            Some(result_recorded_item_recorded_discovering_inner)
                        } else {
                            None
                        };
                    let result_recorded_item_recorded_extended_advertising =
                        if let Some(value) = result_recorded_item.extended_advertising {
                            let result_recorded_item_recorded_extended_advertising_inner = value;
                            Some(result_recorded_item_recorded_extended_advertising_inner)
                        } else {
                            None
                        };
                    let result_recorded_item_recorded = BluetoothadapterdescriptorReplayRecord {
                        id: result_recorded_item_recorded_id,
                        name: result_recorded_item_recorded_name,
                        powered: result_recorded_item_recorded_powered,
                        discovering: result_recorded_item_recorded_discovering,
                        extended_advertising: result_recorded_item_recorded_extended_advertising,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = DeviceBluetoothAdapterListReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceBluetoothAdapterListReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native =
                        binding.store_slice_with(value.len(), |value_native_values| {
                            for value_native_item in value {
                                let value_native_decoded_id =
                                    binding.store_string_owned(value_native_item.id);
                                let value_native_decoded_name =
                                    binding.store_string_owned(value_native_item.name);
                                let value_native_decoded_powered = value_native_item.powered;
                                let value_native_decoded_discovering =
                                    if let Some(value) = value_native_item.discovering {
                                        let value_native_decoded_discovering_inner = value;
                                        Some(value_native_decoded_discovering_inner)
                                    } else {
                                        None
                                    };
                                let value_native_decoded_extended_advertising =
                                    if let Some(value) = value_native_item.extended_advertising {
                                        let value_native_decoded_extended_advertising_inner = value;
                                        Some(value_native_decoded_extended_advertising_inner)
                                    } else {
                                        None
                                    };
                                let value_native_decoded = BluetoothAdapterDescriptor {
                                    id: value_native_decoded_id,
                                    name: value_native_decoded_name,
                                    powered: value_native_decoded_powered,
                                    discovering: value_native_decoded_discovering,
                                    extended_advertising: value_native_decoded_extended_advertising,
                                };
                                value_native_values.push(value_native_decoded);
                            }
                            Ok(())
                        })?;
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

