                        let result_recorded_serial_read_ready_event_metadata = SerialEventMetadata {
                            timestamp_ns: result_recorded_serial_read_ready_event_metadata_timestamp_ns,
                            sequence: result_recorded_serial_read_ready_event_metadata_sequence,
                        };
