#[inline]
fn destack_device_serial_read_into_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut u64,
    handle: resource::SerialPortHandle,
    buffer: NativeSlice<u8>,
    timeoutns: u64,
) -> RuntimeResult<()> {
    let _ = (&handle, &buffer, &timeoutns);

    binding.trace().run_binding_without_context(
        DEVICE_SERIAL_READ_INTO,
        binding.replay_payload_for(DEVICE_SERIAL_READ_INTO)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_device_serial_read_into(
                    binding, out, handle, buffer, timeoutns,
                )
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_device_serial_read_into(
                    binding, out, handle, buffer, timeoutns,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: u64 = unsafe { out.read() };
                let result_recorded = result_value;
                let payload = DeviceSerialReadIntoReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceSerialReadIntoReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    unsafe { out.write(value) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

