#[inline]
fn destack_device_usb_list_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut NativeSlice<UsbDeviceDescriptor>,
) -> RuntimeResult<()> {
    binding.trace().run_binding_without_context(
        DEVICE_USB_LIST,
        binding.replay_payload_for(DEVICE_USB_LIST)?,
        || match world {
            RuntimeWorld::Host => unsafe { platform_native::destack_device_usb_list(binding, out) },
            RuntimeWorld::Simulation => unsafe { platform_simulation_native::destack_device_usb_list(binding, out) },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: NativeSlice<UsbDeviceDescriptor> = unsafe { out.read() };
                let result_recorded_slice = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_slice.len());
                for result_recorded_item in result_recorded_slice.iter().cloned() {
                    let result_recorded_item_recorded_id = unsafe { result_recorded_item.id.as_str()? }.to_string();
                    let result_recorded_item_recorded_usb_version_bcd = if let Some(value) = result_recorded_item.usb_version_bcd {
                        let result_recorded_item_recorded_usb_version_bcd_inner = value;
                        Some(result_recorded_item_recorded_usb_version_bcd_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_device_version_bcd = if let Some(value) = result_recorded_item.device_version_bcd {
                        let result_recorded_item_recorded_device_version_bcd_inner = value;
                        Some(result_recorded_item_recorded_device_version_bcd_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_vendor_id = result_recorded_item.vendor_id;
                    let result_recorded_item_recorded_product_id = result_recorded_item.product_id;
                    let result_recorded_item_recorded_class_code = result_recorded_item.class_code;
                    let result_recorded_item_recorded_subclass_code = result_recorded_item.subclass_code;
                    let result_recorded_item_recorded_protocol_code = result_recorded_item.protocol_code;
                    let result_recorded_item_recorded_manufacturer = if let Some(value) = result_recorded_item.manufacturer {
                        let result_recorded_item_recorded_manufacturer_inner = unsafe { value.as_str()? }.to_string();
                        Some(result_recorded_item_recorded_manufacturer_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_product = if let Some(value) = result_recorded_item.product {
                        let result_recorded_item_recorded_product_inner = unsafe { value.as_str()? }.to_string();
                        Some(result_recorded_item_recorded_product_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_serial_number = if let Some(value) = result_recorded_item.serial_number {
                        let result_recorded_item_recorded_serial_number_inner = unsafe { value.as_str()? }.to_string();
                        Some(result_recorded_item_recorded_serial_number_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_speed = if let Some(value) = result_recorded_item.speed {
                        let result_recorded_item_recorded_speed_inner = value;
                        Some(result_recorded_item_recorded_speed_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_bus_number = if let Some(value) = result_recorded_item.bus_number {
                        let result_recorded_item_recorded_bus_number_inner = value;
                        Some(result_recorded_item_recorded_bus_number_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_port_path = if let Some(value) = result_recorded_item.port_path {
                        let result_recorded_item_recorded_port_path_inner_slice = unsafe { value.as_slice()? };
                        let mut result_recorded_item_recorded_port_path_inner = Vec::with_capacity(result_recorded_item_recorded_port_path_inner_slice.len());
                        for result_recorded_item_recorded_port_path_inner_item in result_recorded_item_recorded_port_path_inner_slice.iter().cloned() {
                            let result_recorded_item_recorded_port_path_inner_item_recorded = result_recorded_item_recorded_port_path_inner_item;
                            result_recorded_item_recorded_port_path_inner.push(result_recorded_item_recorded_port_path_inner_item_recorded);
                        }
                        Some(result_recorded_item_recorded_port_path_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded = UsbdevicedescriptorReplayRecord {
                        id: result_recorded_item_recorded_id,
                        usb_version_bcd: result_recorded_item_recorded_usb_version_bcd,
                        device_version_bcd: result_recorded_item_recorded_device_version_bcd,
                        vendor_id: result_recorded_item_recorded_vendor_id,
                        product_id: result_recorded_item_recorded_product_id,
                        class_code: result_recorded_item_recorded_class_code,
                        subclass_code: result_recorded_item_recorded_subclass_code,
                        protocol_code: result_recorded_item_recorded_protocol_code,
                        manufacturer: result_recorded_item_recorded_manufacturer,
                        product: result_recorded_item_recorded_product,
                        serial_number: result_recorded_item_recorded_serial_number,
                        speed: result_recorded_item_recorded_speed,
                        bus_number: result_recorded_item_recorded_bus_number,
                        port_path: result_recorded_item_recorded_port_path,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = DeviceUsbListReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceUsbListReplayRecord {
                        result,
                    }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native = binding.store_slice_with(value.len(), |value_native_values| {
                        for value_native_item in value {
                            let value_native_decoded_id = binding.store_string_owned(value_native_item.id);
                            let value_native_decoded_usb_version_bcd = if let Some(value) = value_native_item.usb_version_bcd {
                                let value_native_decoded_usb_version_bcd_inner = value;
                                Some(value_native_decoded_usb_version_bcd_inner)
                            } else {
                                None
                            };
                            let value_native_decoded_device_version_bcd = if let Some(value) = value_native_item.device_version_bcd {
                                let value_native_decoded_device_version_bcd_inner = value;
                                Some(value_native_decoded_device_version_bcd_inner)
                            } else {
                                None
                            };
                            let value_native_decoded_vendor_id = value_native_item.vendor_id;
                            let value_native_decoded_product_id = value_native_item.product_id;
                            let value_native_decoded_class_code = value_native_item.class_code;
                            let value_native_decoded_subclass_code = value_native_item.subclass_code;
                            let value_native_decoded_protocol_code = value_native_item.protocol_code;
                            let value_native_decoded_manufacturer = if let Some(value) = value_native_item.manufacturer {
                                let value_native_decoded_manufacturer_inner = binding.store_string_owned(value);
                                Some(value_native_decoded_manufacturer_inner)
                            } else {
                                None
                            };
                            let value_native_decoded_product = if let Some(value) = value_native_item.product {
                                let value_native_decoded_product_inner = binding.store_string_owned(value);
                                Some(value_native_decoded_product_inner)
                            } else {
                                None
                            };
                            let value_native_decoded_serial_number = if let Some(value) = value_native_item.serial_number {
                                let value_native_decoded_serial_number_inner = binding.store_string_owned(value);
                                Some(value_native_decoded_serial_number_inner)
                            } else {
                                None
                            };
                            let value_native_decoded_speed = if let Some(value) = value_native_item.speed {
                                let value_native_decoded_speed_inner = value;
                                Some(value_native_decoded_speed_inner)
                            } else {
                                None
                            };
                            let value_native_decoded_bus_number = if let Some(value) = value_native_item.bus_number {
                                let value_native_decoded_bus_number_inner = value;
                                Some(value_native_decoded_bus_number_inner)
                            } else {
                                None
                            };
                            let value_native_decoded_port_path = if let Some(value) = value_native_item.port_path {
                                let value_native_decoded_port_path_inner = binding.store_slice_with(value.len(), |value_native_decoded_port_path_inner_values| {
                                    for value_native_decoded_port_path_inner_item in value {
                                        let value_native_decoded_port_path_inner_decoded = value_native_decoded_port_path_inner_item;
                                        value_native_decoded_port_path_inner_values.push(value_native_decoded_port_path_inner_decoded);
                                    }
                                    Ok(())
                                })?;
                                Some(value_native_decoded_port_path_inner)
                            } else {
                                None
                            };
                            let value_native_decoded = UsbDeviceDescriptor {
                                id: value_native_decoded_id,
                                usb_version_bcd: value_native_decoded_usb_version_bcd,
                                device_version_bcd: value_native_decoded_device_version_bcd,
                                vendor_id: value_native_decoded_vendor_id,
                                product_id: value_native_decoded_product_id,
                                class_code: value_native_decoded_class_code,
                                subclass_code: value_native_decoded_subclass_code,
                                protocol_code: value_native_decoded_protocol_code,
                                manufacturer: value_native_decoded_manufacturer,
                                product: value_native_decoded_product,
                                serial_number: value_native_decoded_serial_number,
                                speed: value_native_decoded_speed,
                                bus_number: value_native_decoded_bus_number,
                                port_path: value_native_decoded_port_path,
                            };
                            value_native_values.push(value_native_decoded);
                        }
                        Ok(())
                    })?;
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

