#[unsafe(export_name = "destack.device.usb.reset")]
pub(crate) unsafe extern "C" fn destack_device_usb_reset(
    handle: resource::UsbDeviceHandle,
) -> RuntimeStatus {
    native_call(|context| {
        let _ = &handle;

        {
            let (world, _binding_hook_guard) =
                context.on_before_binding_resolve_world(DEVICE_USB_RESET)?;
            match world {
                RuntimeWorld::Host => unsafe {
                    platform_native::destack_device_usb_reset(context, handle)
                },
                RuntimeWorld::Simulation => unsafe {
                    platform_simulation_native::destack_device_usb_reset(context, handle)
                },
            }
        }
    })
}

