/// VM replay implementations for device bindings.
#[inline]
fn destack_device_bluetooth_adapter_list_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        DEVICE_BLUETOOTH_ADAPTER_LIST,
        binding.replay_payload_for(DEVICE_BLUETOOTH_ADAPTER_LIST)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_device_bluetooth_adapter_list(binding, context)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_device_bluetooth_adapter_list(binding, context)
            }
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: VmSlice<BluetoothAdapterDescriptorVm> = value.clone();
                let result_recorded_raw = result_value.raw_values(context)?;
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item =
                        <BluetoothAdapterDescriptorVm as VmAggregateCodec>::decode_with_context(
                            context,
                            result_recorded_item_value,
                        )?;
                    let result_recorded_item_recorded_id = {
                        let result_recorded_item_recorded_id_ref = context
                            .string_ref(result_recorded_item.id)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        result_recorded_item_recorded_id_ref.as_str().to_string()
                    };
                    let result_recorded_item_recorded_name = {
                        let result_recorded_item_recorded_name_ref = context
                            .string_ref(result_recorded_item.name)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        result_recorded_item_recorded_name_ref.as_str().to_string()
                    };
                    let result_recorded_item_recorded_powered = result_recorded_item.powered;
                    let result_recorded_item_recorded_discovering =
                        if let Some(value) = result_recorded_item.discovering {
                            let result_recorded_item_recorded_discovering_inner = value;
                            Some(result_recorded_item_recorded_discovering_inner)
                        } else {
                            None
                        };
                    let result_recorded_item_recorded_extended_advertising =
                        if let Some(value) = result_recorded_item.extended_advertising {
                            let result_recorded_item_recorded_extended_advertising_inner = value;
                            Some(result_recorded_item_recorded_extended_advertising_inner)
                        } else {
                            None
                        };
                    let result_recorded_item_recorded = BluetoothadapterdescriptorReplayRecord {
                        id: result_recorded_item_recorded_id,
                        name: result_recorded_item_recorded_name,
                        powered: result_recorded_item_recorded_powered,
                        discovering: result_recorded_item_recorded_discovering,
                        extended_advertising: result_recorded_item_recorded_extended_advertising,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = DeviceBluetoothAdapterListReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceBluetoothAdapterListReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_builder =
                        VmSlice::<BluetoothAdapterDescriptorVm>::builder(context, value.len())?;
                    for vm_result_item in value {
                        let vm_result_item_value_id = context
                            .string_handle(vm_result_item.id.as_str())
                            .map_err(Box::<RuntimeError>::from)?;
                        let vm_result_item_value_name = context
                            .string_handle(vm_result_item.name.as_str())
                            .map_err(Box::<RuntimeError>::from)?;
                        let vm_result_item_value_powered = vm_result_item.powered;
                        let vm_result_item_value_discovering =
                            if let Some(value) = vm_result_item.discovering {
                                let vm_result_item_value_discovering_inner = value;
                                Some(vm_result_item_value_discovering_inner)
                            } else {
                                None
                            };
                        let vm_result_item_value_extended_advertising =
                            if let Some(value) = vm_result_item.extended_advertising {
                                let vm_result_item_value_extended_advertising_inner = value;
                                Some(vm_result_item_value_extended_advertising_inner)
                            } else {
                                None
                            };
                        let vm_result_item_value = BluetoothAdapterDescriptorVm {
                            id: vm_result_item_value_id,
                            name: vm_result_item_value_name,
                            powered: vm_result_item_value_powered,
                            discovering: vm_result_item_value_discovering,
                            extended_advertising: vm_result_item_value_extended_advertising,
                        };
                        vm_result_builder.push(context, vm_result_item_value)?;
                    }
                    let vm_result = vm_result_builder.finish()?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_device_bluetooth_adapter_list_result(context, result)?;
    Ok(result)
}

