#[inline]
fn destack_device_camera_device_watch_close_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::CameraWatchHandle,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        DEVICE_CAMERA_DEVICE_WATCH_CLOSE,
        binding.replay_payload_for(DEVICE_CAMERA_DEVICE_WATCH_CLOSE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_device_camera_device_watch_close(binding, context, handle)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_device_camera_device_watch_close(
                    binding, context, handle,
                )
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = DeviceCameraDeviceWatchCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceCameraDeviceWatchCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_device_camera_device_watch_close_result(context, result)?;
    Ok(result)
}

