                            let result_recorded_item_recorded_midi_backend_disconnected_event_metadata_dropped_count = value.metadata.dropped_count;
                            let result_recorded_item_recorded_midi_backend_disconnected_event_metadata_source = value.metadata.source;
                            let result_recorded_item_recorded_midi_backend_disconnected_event_metadata_backend = value.metadata.backend;
                            let result_recorded_item_recorded_midi_backend_disconnected_event_metadata = MidiEventMetadata {
                                timestamp_ns: result_recorded_item_recorded_midi_backend_disconnected_event_metadata_timestamp_ns,
                                sequence: result_recorded_item_recorded_midi_backend_disconnected_event_metadata_sequence,
                                dropped_count: result_recorded_item_recorded_midi_backend_disconnected_event_metadata_dropped_count,
                                source: result_recorded_item_recorded_midi_backend_disconnected_event_metadata_source,
                                backend: result_recorded_item_recorded_midi_backend_disconnected_event_metadata_backend,
                            };
                            let result_recorded_item_recorded_midi_backend_disconnected_event_flags = value.flags;
