#[inline]
fn destack_device_midi_input_port_close_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::MidiInputPortHandle,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        DEVICE_MIDI_INPUT_PORT_CLOSE,
        binding.replay_payload_for(DEVICE_MIDI_INPUT_PORT_CLOSE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_device_midi_input_port_close(binding, context, handle)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_device_midi_input_port_close(
                    binding, context, handle,
                )
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = DeviceMidiInputPortCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceMidiInputPortCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_device_midi_input_port_close_result(context, result)?;
    Ok(result)
}

