#[inline]
fn destack_device_serial_list_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        DEVICE_SERIAL_LIST,
        binding.replay_payload_for(DEVICE_SERIAL_LIST)?,
        context,
        |context| {
            match world {
                RuntimeWorld::Host => platform_vm::destack_device_serial_list(binding, context),
                RuntimeWorld::Simulation => platform_simulation_vm::destack_device_serial_list(binding, context),
            }
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: VmSlice<SerialPortDescriptorVm> = value.clone();
                let result_recorded_raw = result_value.raw_values(context)?;
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item = <SerialPortDescriptorVm as VmAggregateCodec>::decode_with_context(context, result_recorded_item_value)?;
                    let result_recorded_item_recorded_id = {
                        let result_recorded_item_recorded_id_ref = context.string_ref(result_recorded_item.id).map_err(|error| RuntimeError::from(error).boxed())?;
                        result_recorded_item_recorded_id_ref.as_str().to_string()
                    };
                    let result_recorded_item_recorded_transport = result_recorded_item.transport;
                    let result_recorded_item_recorded_name = {
                        let result_recorded_item_recorded_name_ref = context.string_ref(result_recorded_item.name).map_err(|error| RuntimeError::from(error).boxed())?;
                        result_recorded_item_recorded_name_ref.as_str().to_string()
                    };
                    let result_recorded_item_recorded_manufacturer = if let Some(value) = result_recorded_item.manufacturer {
                        let result_recorded_item_recorded_manufacturer_inner = {
                            let result_recorded_item_recorded_manufacturer_inner_ref = context.string_ref(value).map_err(|error| RuntimeError::from(error).boxed())?;
                            result_recorded_item_recorded_manufacturer_inner_ref.as_str().to_string()
                        };
                        Some(result_recorded_item_recorded_manufacturer_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_product = if let Some(value) = result_recorded_item.product {
                        let result_recorded_item_recorded_product_inner = {
                            let result_recorded_item_recorded_product_inner_ref = context.string_ref(value).map_err(|error| RuntimeError::from(error).boxed())?;
                            result_recorded_item_recorded_product_inner_ref.as_str().to_string()
                        };
                        Some(result_recorded_item_recorded_product_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_serial_number = if let Some(value) = result_recorded_item.serial_number {
                        let result_recorded_item_recorded_serial_number_inner = {
                            let result_recorded_item_recorded_serial_number_inner_ref = context.string_ref(value).map_err(|error| RuntimeError::from(error).boxed())?;
                            result_recorded_item_recorded_serial_number_inner_ref.as_str().to_string()
                        };
                        Some(result_recorded_item_recorded_serial_number_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_path = match result_recorded_item.path {
                        fs::OsPathVm::OsPathBytes(value) => {
                            let result_recorded_item_recorded_path_os_path_bytes_kind = {
                                let result_recorded_item_recorded_path_os_path_bytes_kind_ref = context.string_ref(value.kind).map_err(|error| RuntimeError::from(error).boxed())?;
                                result_recorded_item_recorded_path_os_path_bytes_kind_ref.as_str().to_string()
                            };
                            let result_recorded_item_recorded_path_os_path_bytes_bytes_inner = value.bytes.0.read_bytes(context)?;
                            let result_recorded_item_recorded_path_os_path_bytes_bytes = result_recorded_item_recorded_path_os_path_bytes_bytes_inner;
                            let result_recorded_item_recorded_path_os_path_bytes = fs::OspathbytesReplayRecord {
                                kind: result_recorded_item_recorded_path_os_path_bytes_kind,
                                bytes: result_recorded_item_recorded_path_os_path_bytes_bytes,
                            };
                            fs::OspathReplayRecord::OsPathBytes(result_recorded_item_recorded_path_os_path_bytes)
                        }
                        fs::OsPathVm::OsPathUtf16(value) => {
                            let result_recorded_item_recorded_path_os_path_utf16_kind = {
                                let result_recorded_item_recorded_path_os_path_utf16_kind_ref = context.string_ref(value.kind).map_err(|error| RuntimeError::from(error).boxed())?;
                                result_recorded_item_recorded_path_os_path_utf16_kind_ref.as_str().to_string()
                            };
                            let result_recorded_item_recorded_path_os_path_utf16_utf16_inner_raw = value.utf16.0.raw_values(context)?;
                            let mut result_recorded_item_recorded_path_os_path_utf16_utf16_inner = Vec::with_capacity(result_recorded_item_recorded_path_os_path_utf16_utf16_inner_raw.len());
                            for result_recorded_item_recorded_path_os_path_utf16_utf16_inner_item_value in result_recorded_item_recorded_path_os_path_utf16_utf16_inner_raw {
                                let result_recorded_item_recorded_path_os_path_utf16_utf16_inner_item = decode_uint16(result_recorded_item_recorded_path_os_path_utf16_utf16_inner_item_value, "result_recorded_item_recorded_path_os_path_utf16_utf16_inner_item", "item")?;
                                let result_recorded_item_recorded_path_os_path_utf16_utf16_inner_item_recorded = result_recorded_item_recorded_path_os_path_utf16_utf16_inner_item;
                                result_recorded_item_recorded_path_os_path_utf16_utf16_inner.push(result_recorded_item_recorded_path_os_path_utf16_utf16_inner_item_recorded);
                            }
                            let result_recorded_item_recorded_path_os_path_utf16_utf16 = result_recorded_item_recorded_path_os_path_utf16_utf16_inner;
                            let result_recorded_item_recorded_path_os_path_utf16 = fs::Ospathutf16ReplayRecord {
                                kind: result_recorded_item_recorded_path_os_path_utf16_kind,
                                utf16: result_recorded_item_recorded_path_os_path_utf16_utf16,
                            };
                            fs::OspathReplayRecord::OsPathUtf16(result_recorded_item_recorded_path_os_path_utf16)
                        }
                    };
                    let result_recorded_item_recorded_usb_vendor_id = if let Some(value) = result_recorded_item.usb_vendor_id {
                        let result_recorded_item_recorded_usb_vendor_id_inner = value;
                        Some(result_recorded_item_recorded_usb_vendor_id_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_usb_product_id = if let Some(value) = result_recorded_item.usb_product_id {
                        let result_recorded_item_recorded_usb_product_id_inner = value;
                        Some(result_recorded_item_recorded_usb_product_id_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded_bluetooth_service_class_id = if let Some(value) = result_recorded_item.bluetooth_service_class_id {
                        let result_recorded_item_recorded_bluetooth_service_class_id_inner = {
                            let result_recorded_item_recorded_bluetooth_service_class_id_inner_ref = context.string_ref(value).map_err(|error| RuntimeError::from(error).boxed())?;
                            result_recorded_item_recorded_bluetooth_service_class_id_inner_ref.as_str().to_string()
                        };
                        Some(result_recorded_item_recorded_bluetooth_service_class_id_inner)
                    } else {
                        None
                    };
                    let result_recorded_item_recorded = SerialportdescriptorReplayRecord {
                        id: result_recorded_item_recorded_id,
                        transport: result_recorded_item_recorded_transport,
                        name: result_recorded_item_recorded_name,
                        manufacturer: result_recorded_item_recorded_manufacturer,
                        product: result_recorded_item_recorded_product,
                        serial_number: result_recorded_item_recorded_serial_number,
                        path: result_recorded_item_recorded_path,
                        usb_vendor_id: result_recorded_item_recorded_usb_vendor_id,
                        usb_product_id: result_recorded_item_recorded_usb_product_id,
                        bluetooth_service_class_id: result_recorded_item_recorded_bluetooth_service_class_id,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = DeviceSerialListReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceSerialListReplayRecord {
                        result,
                    }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_builder = VmSlice::<SerialPortDescriptorVm>::builder(context, value.len())?;
                    for vm_result_item in value {
                        let vm_result_item_value_id = context.string_handle(vm_result_item.id.as_str()).map_err(Box::<RuntimeError>::from)?;
                        let vm_result_item_value_transport = vm_result_item.transport;
                        let vm_result_item_value_name = context.string_handle(vm_result_item.name.as_str()).map_err(Box::<RuntimeError>::from)?;
                        let vm_result_item_value_manufacturer = if let Some(value) = vm_result_item.manufacturer {
                            let vm_result_item_value_manufacturer_inner = context.string_handle(value.as_str()).map_err(Box::<RuntimeError>::from)?;
                            Some(vm_result_item_value_manufacturer_inner)
                        } else {
                            None
                        };
                        let vm_result_item_value_product = if let Some(value) = vm_result_item.product {
                            let vm_result_item_value_product_inner = context.string_handle(value.as_str()).map_err(Box::<RuntimeError>::from)?;
                            Some(vm_result_item_value_product_inner)
                        } else {
                            None
                        };
                        let vm_result_item_value_serial_number = if let Some(value) = vm_result_item.serial_number {
                            let vm_result_item_value_serial_number_inner = context.string_handle(value.as_str()).map_err(Box::<RuntimeError>::from)?;
                            Some(vm_result_item_value_serial_number_inner)
                        } else {
                            None
                        };
                        let vm_result_item_value_path = match vm_result_item.path {
                            fs::OspathReplayRecord::OsPathBytes(value) => {
                                let vm_result_item_value_path_os_path_bytes_kind = context.string_handle(value.kind.as_str()).map_err(Box::<RuntimeError>::from)?;
                                let vm_result_item_value_path_os_path_bytes_bytes_inner = VmArray::<u8>::from_bytes(context, value.bytes.as_ref())?;
                                let vm_result_item_value_path_os_path_bytes_bytes = platform_fs::PathBytesAbi::<platform_abi::VmAbi>(vm_result_item_value_path_os_path_bytes_bytes_inner);
                                let vm_result_item_value_path_os_path_bytes = fs::OsPathBytesVm {
                                    kind: vm_result_item_value_path_os_path_bytes_kind,
                                    bytes: vm_result_item_value_path_os_path_bytes_bytes,
                                };
                                fs::OsPathVm::OsPathBytes(vm_result_item_value_path_os_path_bytes)
                            }
                            fs::OspathReplayRecord::OsPathUtf16(value) => {
                                let vm_result_item_value_path_os_path_utf16_kind = context.string_handle(value.kind.as_str()).map_err(Box::<RuntimeError>::from)?;
                                let mut vm_result_item_value_path_os_path_utf16_utf16_inner_builder = VmArray::<u16>::builder(context, value.utf16.len())?;
                                for vm_result_item_value_path_os_path_utf16_utf16_inner_item in value.utf16 {
                                    let vm_result_item_value_path_os_path_utf16_utf16_inner_item_value = vm_result_item_value_path_os_path_utf16_utf16_inner_item;
                                    vm_result_item_value_path_os_path_utf16_utf16_inner_builder.push(context, vm_result_item_value_path_os_path_utf16_utf16_inner_item_value)?;
                                }
                                let vm_result_item_value_path_os_path_utf16_utf16_inner = vm_result_item_value_path_os_path_utf16_utf16_inner_builder.finish()?;
                                let vm_result_item_value_path_os_path_utf16_utf16 = platform_fs::PathUtf16Abi::<platform_abi::VmAbi>(vm_result_item_value_path_os_path_utf16_utf16_inner);
                                let vm_result_item_value_path_os_path_utf16 = fs::OsPathUtf16Vm {
                                    kind: vm_result_item_value_path_os_path_utf16_kind,
                                    utf16: vm_result_item_value_path_os_path_utf16_utf16,
                                };
                                fs::OsPathVm::OsPathUtf16(vm_result_item_value_path_os_path_utf16)
                            }
                        };
                        let vm_result_item_value_usb_vendor_id = if let Some(value) = vm_result_item.usb_vendor_id {
                            let vm_result_item_value_usb_vendor_id_inner = value;
                            Some(vm_result_item_value_usb_vendor_id_inner)
                        } else {
                            None
                        };
                        let vm_result_item_value_usb_product_id = if let Some(value) = vm_result_item.usb_product_id {
                            let vm_result_item_value_usb_product_id_inner = value;
                            Some(vm_result_item_value_usb_product_id_inner)
                        } else {
                            None
                        };
                        let vm_result_item_value_bluetooth_service_class_id = if let Some(value) = vm_result_item.bluetooth_service_class_id {
                            let vm_result_item_value_bluetooth_service_class_id_inner = context.string_handle(value.as_str()).map_err(Box::<RuntimeError>::from)?;
                            Some(vm_result_item_value_bluetooth_service_class_id_inner)
                        } else {
                            None
                        };
                        let vm_result_item_value = SerialPortDescriptorVm {
                            id: vm_result_item_value_id,
                            transport: vm_result_item_value_transport,
                            name: vm_result_item_value_name,
                            manufacturer: vm_result_item_value_manufacturer,
                            product: vm_result_item_value_product,
                            serial_number: vm_result_item_value_serial_number,
                            path: vm_result_item_value_path,
                            usb_vendor_id: vm_result_item_value_usb_vendor_id,
                            usb_product_id: vm_result_item_value_usb_product_id,
                            bluetooth_service_class_id: vm_result_item_value_bluetooth_service_class_id,
                        };
                        vm_result_builder.push(context, vm_result_item_value)?;
                    }
                    let vm_result = vm_result_builder.finish()?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_device_serial_list_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_device_serial_open_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    id: vm::StringHandle,
    options: SerialPortOpenOptionsVm,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        DEVICE_SERIAL_OPEN,
        binding.replay_payload_for(DEVICE_SERIAL_OPEN)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_device_serial_open(binding, context, id, options)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_device_serial_open(binding, context, id, options)
            }
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: resource::SerialPortHandle = value.clone();
                let result_recorded = result_value;
                let payload = DeviceSerialOpenReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceSerialOpenReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_device_serial_open_result(context, result)?;
    Ok(result)
}

