#[inline]
fn destack_device_serial_read_into_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::SerialPortHandle,
    buffer: VmSlice<u8>,
    timeoutns: u64,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        DEVICE_SERIAL_READ_INTO,
        binding.replay_payload_for(DEVICE_SERIAL_READ_INTO)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_device_serial_read_into(
                binding, context, handle, buffer, timeoutns,
            ),
            RuntimeWorld::Simulation => platform_simulation_vm::destack_device_serial_read_into(
                binding, context, handle, buffer, timeoutns,
            ),
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: u64 = value.clone();
                let result_recorded = result_value;
                let payload = DeviceSerialReadIntoReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    DeviceSerialReadIntoReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_device_serial_read_into_result(context, result)?;
    Ok(result)
}

